template<class T>
void std::atomic_store(std::shared_ptr<T>* p, std::shared_ptr<T> r, std::memory_order mo = std::memory_order_seq_cst);
// Implementation notes: 'p' must not be null; 'mo' affects the memory ordering model. The compiler translates this to hardware atomic stores, e.g., on x86, it might emit a LOCK XCHG or MOV with a memory fence based on 'mo'. For shared_ptr, this ensures the control block's reference count is updated atomically to prevent races.
